#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> l(n);
    for (int i = 0; i < n; ++i) {
        cin >> l[i];
    }
    vector<int> half1, half2;
    int len1 = n / 2;
    int len2 = n - len1;
    for (int i = 0; i < len1; ++i) {
        half1.push_back(l[i]);
    }
    for (int i = len1; i < n; ++i) {
        half2.push_back(l[i]);
    }
    int limit1 = 1 << len1;
    int limit2 = 1 << len2;
    vector<int> subset_sums1, subset_sums2;
    for (int mask = 0; mask < limit1; ++mask) {
        int total = 0;
        for (int bit = 0; bit < len1; ++bit) {
            if (mask & (1 << bit)) {
                total += half1[bit];
            }
        }
        subset_sums1.push_back(total % m);
    }
    for (int mask = 0; mask < limit2; ++mask) {
        int total = 0;
        for (int bit = 0; bit < len2; ++bit) {
            if (mask & (1 << bit)) {
                total += half2[bit];
            }
        }
        subset_sums2.push_back(total % m);
    }
    sort(subset_sums1.begin(), subset_sums1.end());
    sort(subset_sums2.begin(), subset_sums2.end());

    int max_mod = 0;

    auto binary_search = [&](const vector<int>& arr, int val) {
        int left = 0, right = (int)arr.size() - 1;
        int res = 0;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (arr[mid] < val) {
                res = arr[mid];
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return res;
    };

    for (int s : subset_sums1) {
        int target = m - s;
        int candidate = binary_search(subset_sums2, target);
        max_mod = max(max_mod, (s + candidate) % m);
    }

    cout << max_mod << "\n";

    return 0;
}
